import{_ as o,o as r,c as a,a2 as i}from"./chunks/framework.DdtnLau3.js";const c=JSON.parse('{"title":"开始使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/index.md","filePath":"zh/guide/index.md"}'),t={name:"zh/guide/index.md"};function n(p,e,s,h,l,d){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h1><p><strong>Core</strong> 在 Linux Docker 主机上管理 Work、Agent、Service 和数据；<strong>CLI</strong> 提供终端用户命令。首次试用在同一台 Linux 电脑完成，需要受支持的模型提供方和 API key。</p><ol><li><a href="/piwork/zh/guide/quick-start.html">快速开始</a>：默认 Docker run，终端登录、创建 Work并收到回复；原生 CLI 是折叠选项。</li><li><a href="/piwork/zh/guide/installation.html">安装与部署</a>：环境要求、可选 Core Compose Demo、故障处理和恢复。</li><li><a href="/piwork/zh/guide/first-work.html">第一个 Work</a>：终端文件任务，以及停止、导出、导入和继续使用。</li></ol><p>已有配置完成的 Core 时，直接使用快速开始中的 CLI 入口。</p><p>需要开发应用？<a href="/piwork/zh/guide/web-development.html">Web 开发指南</a>介绍默认基础镜像、自动生效、sqlite3、持久化与升级。</p><p>配置模型请阅读 <a href="/piwork/zh/guide/ai-models.html">AI 模型</a>：单表单添加、消息 Test、Runtime 默认选择及 Work/Thinking 升级边界。</p><h2 id="当前支持范围" tabindex="-1">当前支持范围 <a class="header-anchor" href="#当前支持范围" aria-label="Permalink to &quot;当前支持范围&quot;">​</a></h2><p>已发行 0.0.2 Preview 的镜像为 linux/amd64，Core 使用 Linux rootful Docker Engine 28+ 和本机 Unix socket。客户端支持 Linux 或 Windows Docker Desktop 的 Linux 容器模式，Windows 客户端连接 Linux Core。Compose 2.24+ 仅用于可选 Core Demo 或高级部署。</p><p>WSL2 用户须有可用的 Linux Engine Unix socket；具体测试环境与边界见<a href="https://github.com/pphboy/piwork/blob/main/docs/docker-quickstart-acceptance.md" target="_blank" rel="noreferrer">上游终端验收记录</a>。Desktop 仍作为独立用户入口提供，终端试用不依赖它。</p><p><a href="/piwork/zh/spec/">规范概览</a>记录源码与镜像来源，应用示例见 <a href="/piwork/zh/demo/kanban.html">Kanban Work</a>。</p><p><a href="/piwork/zh/guide/quick-start.html">终端 Quick Start</a> 使用独立 Core/CLI 镜像，Core 可单独采用 Compose；合并方式见单机部署示例，原生构建与管理员操作见独立导航。</p>',11)])])}const u=o(t,[["render",n]]);export